CREATE TABLE `DBA_SPMonitor` (   `RowID` bigint unsigned NOT NULL AUTO_INCREMENT,   `Database` varchar(64) DEFAULT NULL,   `GroupID` int DEFAULT NULL,   `Name` varchar(64) DEFAULT NULL,   `Type` varchar(64) DEFAULT NULL,   `Count_Star` bigint unsigned DEFAULT NULL,   `Count_Star_Flag` bigint unsigned DEFAULT NULL,   `Sum_Errors` bigint unsigned DEFAULT NULL,   `Sum_Errors_Flag` bigint unsigned DEFAULT NULL,   `Sum_Warnings` bigint unsigned DEFAULT NULL,   `Sum_Warnings_Flag` bigint unsigned DEFAULT NULL,   `Sum_Rows_Affected` bigint unsigned DEFAULT NULL,   `Sum_Rows_Affected_Flag` bigint unsigned DEFAULT NULL,   `Sum_Rows_Sent` bigint unsigned DEFAULT NULL,   `Sum_Rows_Sent_Flag` bigint unsigned DEFAULT NULL,   `Created` datetime DEFAULT CURRENT_TIMESTAMP,   PRIMARY KEY (`RowID`),   KEY `IX_SPMonitor_Created` (`Created` DESC) ) ENGINE=InnoDB AUTO_INCREMENT=0;